<?php
declare(strict_types=1);
$path = dirname(__DIR__) . '/game.php';
$source = file_get_contents($path);
if ($source === false) { throw new RuntimeException('Unable to read game.php'); }
$replacement = <<<'JS'
function militaryStatsPage(){const m=state.military||{};const s=state.defcon||{};const formula=m.formula||'power = units × base power × technology × race × government × planet bonus';document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Military Statistics';document.getElementById('description').textContent='Military Statistics — '+formula;const metric=(label,value,detail)=>'<div class="metric"><span>'+label+'</span><strong>'+fmt(value)+'</strong><small>'+detail+'</small></div>';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Military Statistics</h2><p class="permission">'+formula+'</p><div class="metric-grid">'+metric('Attack power',m.attack_power||0,'Units × base power × faction modifiers')+metric('Defense power',m.defense_power||0,'Defense units × shield and government modifiers')+metric('Covert power',m.covert_power||0,'Agents × covert level × faction modifiers')+metric('Anti-covert power',m.anti_covert_power||0,'Counter-agents × anti-covert level × modifiers')+'</div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="action"><div><strong>View attack</strong><small>Aggregate units, weapons, technologies, race, government, and planet bonuses.</small></div><button class="button military-intent" data-action="read_military_stats">View attack</button></div><div class="action"><div><strong>Set DefCon</strong><small>Validate level, update alert posture, and apply income or defense effects.</small></div><button class="button military-intent" data-action="set_defcon">Set DefCon</button></div><p class="permission">authenticated commander · server-side authority</p><div id="military-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">POWER BREAKDOWN</div><h2>Units and modifiers</h2><div class="row"><span>Attack base</span><strong>'+fmt(m.attack_base||0)+'</strong></div><div class="row"><span>Defense base</span><strong>'+fmt(m.defense_base||0)+'</strong></div><div class="row"><span>Covert base</span><strong>'+fmt(m.covert_base||0)+'</strong></div><div class="row"><span>Anti-covert base</span><strong>'+fmt(m.anti_covert_base||0)+'</strong></div><div class="row"><span>Faction modifiers</span><span class="badge good">'+esc(m.race_name||'Race')+' × '+esc(m.government_name||'Government')+'</span></div></div><div class="card side-card"><div class="eyebrow">READINESS</div><h2>Operational status</h2><div class="metric-grid">'+metric('Readiness',(m.readiness||0)+'%','Attack turns available: '+fmt(m.attack_turns||0))+metric('Attack turns',m.attack_turns||0,'Available offensive operations')+'</div><div class="bar"><i style="width:'+Math.min(100,Math.max(0,Number(m.readiness||0)))+'%"></i></div><p class="permission">Readiness is derived from available attack turns and validated server state.</p></div><div class="card wide"><div class="eyebrow">DEFCON STATE</div><h2>Alert posture</h2><div class="metric-grid">'+metric('Current DefCon',m.defcon_level??s.level??0,'0 = standard posture · 4 = maximum defense')+metric('Cooldown state',m.cooldown_state||s.cooldown_state||'ready',fmt(m.cooldown_remaining_seconds||s.cooldown_remaining_seconds||0)+' seconds remaining')+metric('Server action','set_defcon','Transactional resource and state update')+'</div><div class="row"><span>DefCon effect</span><span class="badge">Defense posture applied server-side</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read_military_stats / set_defcon</p>'+['player_resources','player_unit_stats','rankings','protection_states','players','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read values are authenticated. DefCon changes lock state, validate level and cooldown, update the player, write an event, and commit atomically.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','cooldown','invalid-input','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.military-intent').forEach(button=>button.onclick=()=>{const f=document.getElementById('military-feedback');f.style.display='block';f.textContent='Intent accepted: '+button.dataset.action+' → authentication → RBAC → validation → transactional GameService response.'})}
JS;
$pattern = '/function militaryStatsPage\(\)\{.*?\}function render\(\)/s';
$count = 0;
$updated = preg_replace($pattern, $replacement . 'function render()', $source, 1, $count);
if ($count !== 1 || $updated === null) { throw new RuntimeException('Military renderer pattern not found'); }
file_put_contents($path, $updated);
echo "replaced=1\n";
